def main():
    research=json.loads((ROOT/'analysis/women-biographies-research.json').read_text('utf8'))
    files=[ROOT/'translation'/n for n in ('interface.json','gameplay-dialogue.json','relocated-text.json')]
    data={p:json.loads(p.read_text('utf8')) for p in files}
    by_offset={e['offset']:e for rows in data.values() for e in rows if e['file']=='INIT.PRG;1'}
    audit=[]
    for r in research:
        i=r['index'];e=by_offset[r['bio_offset']]
        row=dict(index=i,name={13:'Юдит',15:'Элеонора',38:'Шира',76:'Муарун'}.get(i,r['name']),previous_name=r['name'],japanese=unicodedata.normalize('NFKC',r['name_ja']),original_description=r['ja'])
        if i in H:
            prose,urls=H[i]
            lines=textwrap.wrap(prose,22,break_long_words=False,break_on_hyphens=False)
            assert len(lines)<=7 and all(len(x)<=22 for x in lines),(i,lines)
            e['ru']='\n'.join(lines);e['max_columns']=22;e['max_lines']=7
            row.update(status='historical_context' if i in (13,61,65) else 'historical_or_literary',sources=urls,biography=e['ru'])
        else:
            row.update(status='identity_unresolved',sources=[],biography=e['ru'])
        row['identity_note']=NOTES.get(i,'Японское имя и родственные либо биографические сведения исходника согласуются с указанными источниками.')
        audit.append(row)
    # Remove demonstrably impossible kinship rather than substitute a different queen.
    e=by_offset[research[26]['bio_offset']]
    e['ru']='Исторический прообраз\nточно не установлен.'
    audit[26]['biography']=e['ru']
    for rows in data.values():
        for e in rows:
            ja=unicodedata.normalize('NFKC',re.sub(r'\x1b[KH]','',e['ja'])).strip()
            corrections={'シイラ':'Шира','ムアルン':'Муарун','エリーナ':'Элеонора','エウジット':'Юдит'}
            if ja in corrections:
                e['ru']=corrections[ja]
                # This correction intentionally supersedes the old MD spelling.
                e.pop('md_key',None);e.pop('md_section',None)
    for p,rows in data.items():p.write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n','utf8')
    (ROOT/'analysis/women-history-audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n','utf8')
    doc=['# Женщины справочника: проверка имён и биографий','',
         'Проверены 84 исходные записи Sega CD. 51 историческая или литературная справка переработана по источникам. Для 33 записей историческая идентичность не установлена надёжно. Это не означает, что персонажи доказанно вымышлены.',
         '', 'Японские имена сверялись вместе с родством и описанием оригинала. Совпадение с тёзкой из другой эпохи не считается доказательством. У Юдит и Торэгэнэ оригинал сообщает лишь о совпадении имени; это оговорено в тексте. Рэйко — игровое имя исторической жены Хидэхиры. Эпизоды из Повести о доме Тайра обозначены как литературные.',
         '', 'Игровые сведения о детях вынесены под имя и взяты из исходных японских описаний. Они не являются историческими фактами и не меняют характеристики персонажей.',
         '', '## Все записи','']
    for a in audit:
        doc += [f"### {a['index']+1}. {a['name']} — {a['japanese']}",'',a['identity_note'],'']
        if a['sources']:
            doc += ['Текст: '+a['biography'].replace('\n',' '),'']
            doc += [f'- [Источник {n+1}]({url})' for n,url in enumerate(a['sources'])]+['']
        else:doc += ['Подтверждённая историческая биография не добавлена. Сохранены игровые сведения, кроме исправления противоречивого родства Клеменции.','']
    (ROOT/'analysis/women-history-sources.md').write_text('\n'.join(doc)+'\n','utf8')
    print(f'{len(audit)} original identities reviewed; {len(H)} researched biographies, one contradictory biography corrected')

if __name__=='__main__':main()
